  const playing = segPlayback.materialId === m.id && segPlayback.playing;
  // SIRA (v2.199): Dinle → Kontrol → ↑/↓ → Onayla. Kullanıcının dar ekranda
  // kaydırmadan yaptığı tur budur: dinle, karar ver, sonrakine geç. Kontrol
