// Bölüm bitince sıradakine geçer. Döner: true = kuyruk işi devraldı.
function advanceSpeakerQueue(m, player) {
  if (!spkQueue.on || spkQueue.materialId !== (m && m.id)) return false;
  spkQueue.pos += 1;
  if (spkQueue.pos >= spkQueue.indexes.length) {
    stopSpeakerQueue();
    showToast('Konuşmacı dinlemesi bitti.');
    return true;
  }
  const card = $(`#segments-${CSS.escape(m.id)}`)?.closest('.audio-card');
  const i = spkQueue.indexes[spkQueue.pos];
  const s = (m.segments || [])[i];
  if (!card || !s) {
    stopSpeakerQueue();
    return true;
  }
  playSegmentRange(card, m, s, i, { restart: true });
  return true;
}
// Hiçbir bölüme atanmamış konuşmacıları temizler. Raporda görünmeyen ama
// listede kalan eski etiketler (K, E, S1, S2…) böylece kalkar.
function unusedSpeakers(m) {
  return (m.speakers || []).filter((sp) => speakerSegments(m, sp).length === 0);
}
function fmtHz(hz) {
  return hz ? `${Math.round(hz)} Hz` : '';
}

// Temel frekans (f0) tahmini: otokorelasyon yöntemi. Bir bölümün ortasından
// 0,4 sn'lik pencere alınır, 70-400 Hz aralığında en güçlü periyodiklik aranır.
// Bu gerçek bir DSP ölçümüdür; sonuç "kayıt koşullarına bağlı tahmin" olarak
// sunulur. Kullanıcı ölçümü tetikler, uygulama kendiliğinden çalıştırmaz.
function detectPitchHz(samples, sampleRate) {
  const N = Math.min(samples.length, Math.floor(sampleRate * 0.4));
  if (N < sampleRate * 0.05) return null;
  const buf = new Float32Array(N);
  let mean = 0;
  for (let i = 0; i < N; i++) {
    buf[i] = samples[i];
    mean += buf[i];
  }
  mean /= N;
  for (let i = 0; i < N; i++) buf[i] -= mean; // DC bileşenini çıkar
  let r0 = 0;
  for (let i = 0; i < N; i++) r0 += buf[i] * buf[i];
  if (r0 <= 0) return null;
  const minLag = Math.max(2, Math.floor(sampleRate / 400)),
    maxLag = Math.floor(sampleRate / 70);
  let bestLag = -1,
    bestNorm = 0;
  for (let lag = minLag; lag <= maxLag && lag < N; lag++) {
    let corr = 0;
    for (let i = 0; i < N - lag; i++) corr += buf[i] * buf[i + lag];
    // Normalize otokorelasyon: r(lag)/r(0). 1'e yakın = güçlü periyodiklik.
    const norm = corr / r0;
    if (norm > bestNorm) {
      bestNorm = norm;
      bestLag = lag;
    }
  }
  if (bestLag < 0 || bestNorm < 0.3) return null; // yeterli periyodiklik yok
  return sampleRate / bestLag;
}
// OKTAV BELİRSİZLİĞİ (v2.101).
// Otokorelasyon, temel frekans (H1) zayıf ve 2. harmonik (H2) güçlü olduğunda
// H2'nin periyodunu bulur ve perdeyi İKİ KATINA çıkarır (ölçüldü: gerçek
// 120 Hz → 238,8 Hz). Bunu otokorelasyondan ayırmak GÜVENİLİR biçimde mümkün
// değildir: her periyodik sinyal 2×lag'de de tepe verir. "Düzeltme" denemesi
// normal sesleri de bozdu (ölçüldü: 210 Hz → 105 Hz).
// DÜRÜST ÇÖZÜM: belirsizliği TESPİT ET ve BİLDİR. Spektrumda H1 bileşeni
// H2'den belirgin biçimde zayıfsa (≥ 10 dB), ölçülen perde oktav yukarıda
// olabilir; rapor bunu "oktav belirsiz" diye yazar ve tek bir kesin sayı
// iddia etmez. Uydurma yok, ölçülemeyen kesinlik iddia edilmez.
function detectPitchAmbiguity(samples, sampleRate, measuredHz) {
  if (!measuredHz) return { ambiguous: false, octaveHz: null };
  const N = Math.min(samples.length, Math.floor(sampleRate * 0.4));
  if (N < sampleRate * 0.05) return { ambiguous: false, octaveHz: null };
  // Basit Goertzel: f ve 2f'deki enerji oranı.
  const power = (freq) => {
    const w = (2 * Math.PI * freq) / sampleRate;
    const c = 2 * Math.cos(w);
    let s1 = 0,
      s2 = 0;
    for (let i = 0; i < N; i++) {
      const s0 = samples[i] + c * s1 - s2;
      s2 = s1;
      s1 = s0;
    }
    return s1 * s1 + s2 * s2 - c * s1 * s2;
  };
  const fHalf = measuredHz / 2; // oktav aşağısı
  if (fHalf < 70) return { ambiguous: false, octaveHz: null };
  const pMeas = power(measuredHz);
  const pHalf = power(fHalf);
  if (!(pMeas > 0)) return { ambiguous: false, octaveHz: null };
  // Ölçülen frekansın YARISINDA anlamlı enerji varsa, gerçek temel o olabilir:
  // ölçülen aslında 2. harmoniktir (oktav yukarıda). Eşik −30 dB: bu kadar
  // zayıf bir bileşen bile "yarım frekansta enerji var" demektir; normal
  // seslerde f/2'de enerji pratikte YOKTUR (ölçüldü: −250 dB civarı).
  const ratioDb = 10 * Math.log10(Math.max(pHalf, 1e-20) / pMeas);
  const ambiguous = ratioDb > -30;
  return { ambiguous, octaveHz: ambiguous ? fHalf : null, ratioDb };
}
// Bölüm → konuşmacı kaydı (kimlik VEYA ad). Ölçüm ve işaretler bunu kullanır.
function speakerForSegment(m, s) {
  if (!m || !s) return null;
  const id = String(s.speakerId || '');
  const byId = id ? (m.speakers || []).find((x) => x.id === id) : null;
  if (byId) return byId;
  const name = String(s.speaker || '');
  return name ? (m.speakers || []).find((x) => x.name === name) || null : null;
}
// KONUŞMACI SES TUTARLILIĞI (v2.265): bölüm bazında perde ölçer, konuşmacı
// profilleriyle karşılaştırır. İŞARET üretir; otomatik değiştirmez.
// Ölçüm yalnız kullanıcı tetiklediğinde çalışır (ağır decode).
async function measureSpeakerConsistency(m) {
  const c = currentCase();
  const segs = (m && m.segments) || [];
  if (!segs.length) {
    showToast('Önce bölümleyin; ölçülecek bölüm yok.');
    return;
  }
  const blob = await getAudioBlob(c, m);
  if (!blob) {
    showToast('Ses dosyası bulunamadı.');
    return;
  }
  showToast('Konuşmacı ses tutarlılığı ölçülüyor…');
  const AC = window.AudioContext || window.webkitAudioContext;
  const ctx = new AC();
  let audio;
  try {
    audio = await ctx.decodeAudioData(await blob.arrayBuffer());
  } catch (e) {
    await ctx.close();
    showToast('Ses çözümlenemedi.');
    return;
  }
  const sr = audio.sampleRate;
  const channels = [];
  for (let ch = 0; ch < audio.numberOfChannels; ch++) channels.push(audio.getChannelData(ch));
  const points = [];
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    const sp = speakerForSegment(m, s);
    if (!sp) continue;
    const st = secondsFromTimecode(s.start);
    const en = secondsFromTimecode(s.end);
    if (!(en > st)) continue;
    // Bölümün iki noktasından 0,25 sn'lik pencere: tek pencereye göre daha
    // dayanıklı; tüm bölümü taramak 300 bölümde dakikalar alırdı.
    const vals = [];
    for (const frac of [0.3, 0.7]) {
      const mid = st + (en - st) * frac;
      const a = Math.max(0, Math.floor((mid - 0.125) * sr));
      const b = Math.min(channels[0].length, Math.floor((mid + 0.125) * sr));
      if (b - a < sr * 0.05) continue;
      const segCh = channels.map((ch) => ch.subarray(a, b));
      const pick = pickActiveChannel(segCh);
      const f = detectPitchHz(segCh[pick.index], sr);
      if (!f) continue;
      const amb = detectPitchAmbiguity(segCh[pick.index], sr, f);
      vals.push({ hz: f, ambiguous: !!(amb && amb.ambiguous) });
    }
    const good = vals.filter((v) => !v.ambiguous).map((v) => v.hz);
    const hz = medianOf(good);
    // Oktav belirsiz ölçüm profile girmez; ama "ölçülemedi" de yazılmaz.
    points.push({ index: i, speakerId: sp.id, hz, ambiguous: vals.length > 0 && good.length === 0 });
  }
  await ctx.close();
  const profiles = speakerVoiceProfiles(points);
  const outliers = voiceOutliers(points, profiles);
  const changes = voiceChangeSuspects(points);
  m.voiceCheck = {
    ok: true,
    schema: VOICE_SCHEMA,
    at: new Date().toISOString(),
    points,
    profiles,
    outliers,
    changes
  };
  logEvent(
    m,
    'Konuşmacı tutarlılığı ölçüldü',
    `${points.length} bölüm · ${outliers.length} şüpheli · ${changes.length} değişim şüphesi (kimlik tespiti değildir)`
  );
  persist();
  refreshMeasurementPanel(m);
  await renderAudioList();
  showToast(
    `Tutarlılık ölçüldü: ${outliers.length} bölüm şüpheli, ${changes.length} değişim şüphesi. ` +
      'İşaretler öneridir; karar sizindir.'
  );
}
// ---- Konuşmacı GÖMME (embedding) ölçümü (v2.279) ------------------------
// Model İSTEĞE BAĞLI indirilir (tek sefer ~97 MB, q8; transformers.js zaten
// ASR için kullanılıyor). Ölçüm yalnız kullanıcı tetiklediğinde çalışır ve
// ATAMA YAPMAZ: yalnız "bu bölüm atandığı kişiye ne kadar benziyor" işareti
// ve atanmamışlar için öneri üretir. Kimlik tespiti değildir.
let speakerEmbedder = null;
let speakerEmbedderLoading = null;
let voiceEmbedRunning = false;

async function loadSpeakerEmbedder(onProgress) {
  if (speakerEmbedder) return speakerEmbedder;
  if (speakerEmbedderLoading) return speakerEmbedderLoading;
  speakerEmbedderLoading = (async () => {
    const { AutoProcessor, AutoModel } = await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.7.2');
    const processor = await AutoProcessor.from_pretrained(VOICE_EMBED_MODEL);
    const model = await AutoModel.from_pretrained(VOICE_EMBED_MODEL, {
      dtype: VOICE_EMBED_DTYPE,
      progress_callback: (p) => {
        if (typeof onProgress === 'function') onProgress(p);
      }
    });
    speakerEmbedder = { processor, model, modelId: VOICE_EMBED_MODEL };
    return speakerEmbedder;
  })();
  try {
    return await speakerEmbedderLoading;
  } finally {
    speakerEmbedderLoading = null;
  }
}

// Model 16 kHz ister; kayıt genelde başka hızdadır → çevrimdışı yeniden örnekle.
async function resampleTo16k(f32, srcRate) {
  if (!f32 || !f32.length || !(srcRate > 0)) return f32;
  if (Math.round(srcRate) === VOICE_EMBED_SR) return f32;
  const len = Math.max(1, Math.ceil((f32.length * VOICE_EMBED_SR) / srcRate));
  const off = new OfflineAudioContext(1, len, VOICE_EMBED_SR);
  const buf = off.createBuffer(1, f32.length, srcRate);
  buf.copyToChannel(f32, 0);
  const src = off.createBufferSource();
  src.buffer = buf;
  src.connect(off.destination);
  src.start();
  const out = await off.startRendering();
  return out.getChannelData(0);
}

function voiceEmbedIsMeasured(m) {
  return !!(m && m.voiceEmbed && m.voiceEmbed.ok && m.voiceEmbed.schema === VOICE_EMBED_SCHEMA);
}

async function measureSpeakerEmbeddings(m) {
  const c = currentCase();
  const segs = (m && m.segments) || [];
  if (!segs.length) {
    showToast('Önce bölümleyin; ölçülecek bölüm yok.');
    return;
  }
  if (voiceEmbedRunning) {
    showToast('Gömme ölçümü zaten sürüyor; bitmesini bekleyin.');
    return;
  }
  const blob = await getAudioBlob(c, m);
  if (!blob) {
    showToast('Ses dosyası bulunamadı.');
    return;
  }
  if (!speakerEmbedder) {
    const ok = await askConfirm(
      'Konuşmacı gömme modeli',
      `Konuşmacı doğrulama modeli (WavLM-SV, q8) yaklaşık <b>${esc(fmtBytes(VOICE_EMBED_BYTES))}</b> indirilir. ` +
        'İndirme bir kez yapılır ve tarayıcı önbelleğinde kalır. Ölçüm konuşmacı <b>benzerliği</b> verir; ' +
        '<b>kimlik tespiti değildir</b> ve hiçbir atama otomatik değişmez. Devam edilsin mi?'
    );
    if (!ok) return;
  }
  const progressEl = document.getElementById(`ve-progress-${m.id}`);
  const setProgress = (text) => {
    if (progressEl) progressEl.textContent = text;
  };
  voiceEmbedRunning = true;
  try {
    if (!speakerEmbedder) {
      setProgress('Model indiriliyor…');
      await loadSpeakerEmbedder((p) => {
        if (p && p.status === 'progress' && p.total) {
          setProgress(`Model indiriliyor… %${Math.round((p.loaded / p.total) * 100)}`);
        }
      });
    }
    setProgress('Ses çözümleniyor…');
    const AC = window.AudioContext || window.webkitAudioContext;
    const ctx = new AC();
    let audio;
    try {
      audio = await ctx.decodeAudioData(await blob.arrayBuffer());
    } catch (e) {
      await ctx.close();
      showToast('Ses çözümlenemedi.');
      return;
    }
    const sr = audio.sampleRate;
    const channels = [];
    for (let ch = 0; ch < audio.numberOfChannels; ch++) channels.push(audio.getChannelData(ch));
    const points = [];
    let skipped = 0;
    for (let i = 0; i < segs.length; i++) {
      const s = segs[i];
      const st = secondsFromTimecode(s.start);
      const en = secondsFromTimecode(s.end);
      const dur = en - st;
      if (!(dur >= VOICE_EMBED_MIN_SEC)) {
        skipped++;
        continue;
      }
      const span = Math.min(VOICE_EMBED_WINDOW_SEC, dur);
      const mid = st + dur / 2;
      const a = Math.max(0, Math.floor((mid - span / 2) * sr));
      const b = Math.min(channels[0].length, Math.floor((mid + span / 2) * sr));
      if (b - a < sr * VOICE_EMBED_MIN_SEC) {
        skipped++;
        continue;
      }
      const segCh = channels.map((ch) => ch.subarray(a, b));
      const pick = pickActiveChannel(segCh);
      const f32 = await resampleTo16k(segCh[pick.index], sr);
      const inputs = await speakerEmbedder.processor(f32);
      const out = await speakerEmbedder.model(inputs);
      const sp = speakerForSegment(m, s);
      points.push({ index: i, speakerId: sp ? sp.id : '', vec: Array.from(out.embeddings.data) });
      // Vektörler KAYDA YAZILMAZ: yalnız özet saklanır (boyut). Yeniden
      // değerlendirme gerekirse ölçüm tekrar çalıştırılır.
      setProgress(`Ölçülüyor… ${points.length} bölüm`);
      await new Promise((r) => setTimeout(r, 0));
    }
    await ctx.close();
    if (!points.length) {
      showToast(`Ölçülecek yeterli uzunlukta bölüm yok (en az ${VOICE_EMBED_MIN_SEC} sn).`);
      return;
    }
    const profiles = speakerEmbeddingProfiles(points);
    const outliers = embeddingOutliers(points, profiles);
    const changes = embeddingChangeSuspects(points);
    const suggestions = embeddingSuggestions(points, profiles);
    const unassignedPoints = points.filter((p) => {
      const sg = segs[p.index];
      return !(sg && (sg.speakerId || String(sg.speaker || '').trim()));
    });
    const clusters = embeddingClusters(unassignedPoints, { threshold: VOICE_EMBED_SAME, minSize: 2 });
    m.voiceEmbed = {
      ok: true,
      schema: VOICE_EMBED_SCHEMA,
      at: new Date().toISOString(),
      model: VOICE_EMBED_MODEL,
      dtype: VOICE_EMBED_DTYPE,
      dim: VOICE_EMBED_DIM,
      windowSec: VOICE_EMBED_WINDOW_SEC,
      same: VOICE_EMBED_SAME,
      diff: VOICE_EMBED_DIFF,
      measured: points.length,
      skipped,
      profiles: profiles.map((p) => ({ speakerId: p.speakerId, count: p.count })),
      outliers,
      changes,
      suggestions,
      clusters
    };
    logEvent(
      m,
      'Ses gömme ölçümü yapıldı',
      `${points.length} bölüm · ${outliers.length} şüpheli · ${changes.length} değişim şüphesi (kimlik tespiti değildir)`
    );
    persist();
    const scroll = captureSegScroll(m);
    await renderAudioList();
    restoreSegScroll(m, scroll, activeSegIndex(m));
    renderSpeakersPanel(m);
    renderOverview();
    showToast(
      `Gömme ölçümü: ${points.length} bölüm · ${outliers.length} şüpheli · ${changes.length} değişim şüphesi. ` +
        'İşaretler öneridir; atama değiştirilmedi.'
    );
  } catch (e) {
    showToast(`Gömme ölçümü başarısız: ${e && e.message ? e.message : 'bilinmeyen hata'}`);
    if (progressEl) progressEl.textContent = 'Ölçüm başarısız.';
  } finally {
    voiceEmbedRunning = false;
  }
}

// ---- Konuşmacı ÖN-ATAMA (v2.301) ---------------------------------------
// Çözümlemedeki "tümünü çözümle / dosya / bölüm yeniden çözümle" kolaylığının
// konuşmacı karşılığı. Bölüm gömmelerini anonim kümelere ayırıp S1..Sk atar.
// KİMLİK TESPİTİ DEĞİLDİR; öneri/ön-atamadır, uzman dinleyip düzeltir.

// Hedef bölümler için gömme vektörleri. `measureSpeakerEmbeddings` ile aynı
// hattı kullanır (16 kHz'e yeniden örnekleme, en yüksek enerjili kanal).
async function embedSegmentIndexes(m, indexes, { onProgress } = {}) {
  const c = currentCase();
  const blob = await getAudioBlob(c, m);
  if (!blob) return { error: 'noaudio' };
  const AC = window.AudioContext || window.webkitAudioContext;
  const ctx = new AC();
  let audio;
  try {
    audio = await ctx.decodeAudioData(await blob.arrayBuffer());
  } catch (e) {
    await ctx.close();
    return { error: 'decode' };
  }
  const sr = audio.sampleRate;
  const channels = [];
  for (let ch = 0; ch < audio.numberOfChannels; ch++) channels.push(audio.getChannelData(ch));
  const points = [];
  let skipped = 0;
  for (const i of indexes) {
    const s = (m.segments || [])[i];
    if (!s) continue;
    const st = secondsFromTimecode(s.start);
    const en = secondsFromTimecode(s.end);
    const dur = en - st;
    if (!(dur >= VOICE_EMBED_MIN_SEC)) {
      skipped++;
      continue;
    }
    const span = Math.min(VOICE_EMBED_WINDOW_SEC, dur);
    const mid = st + dur / 2;
    const a = Math.max(0, Math.floor((mid - span / 2) * sr));
    const b = Math.min(channels[0].length, Math.floor((mid + span / 2) * sr));
    if (b - a < sr * VOICE_EMBED_MIN_SEC) {
      skipped++;
      continue;
    }
    const segCh = channels.map((ch) => ch.subarray(a, b));
    const pick = pickActiveChannel(segCh);
    const f32 = await resampleTo16k(segCh[pick.index], sr);
    const inputs = await speakerEmbedder.processor(f32);
    const out = await speakerEmbedder.model(inputs);
    points.push({ index: i, vec: Array.from(out.embeddings.data) });
    if (typeof onProgress === 'function') onProgress(points.length);
    await new Promise((r) => setTimeout(r, 0));
  }
  await ctx.close();
  return { points, skipped };
}

// Dosya bazında: BOŞ bölümlerin konuşmacısını otomatik ön-ata. Mevcut
// atamalar KORUNUR (v2.292 "sessiz atama yok" kuralı); onay + geri alma var.
async function autoAssignSpeakers(m) {
  if (!m) return;
  const segs = m.segments || [];
  if (!segs.length) {
    showToast('Önce bölümleyin; atanacak bölüm yok.');
    return;
  }
  if (voiceEmbedRunning) {
    showToast('Konuşmacı ölçümü zaten sürüyor; bitmesini bekleyin.');
    return;
  }
  const targets = [];
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    if (s.speakerId || String(s.speaker || '').trim()) continue; // mevcut atama korunur
    targets.push(i);
  }
  if (!targets.length) {
    showToast('Atanacak boş bölüm yok. Mevcut atamalar korunur.');
    return;
  }
  if (!speakerEmbedder) {
    const ok = await askConfirm(
      'Konuşmacıları önceden belirle',
      `Konuşmacı doğrulama modeli (WavLM-SV, q8) yaklaşık <b>${esc(fmtBytes(VOICE_EMBED_BYTES))}</b> indirilir (bir kez). ` +
        'Bölümler ses benzerliğine göre <b>anonim</b> gruplara (S1, S2…) ayrılır; bu <b>kimlik tespiti değildir</b>. ' +
        'Atamalar <b>öneri</b>dir; dinleyip düzeltirsiniz ve <b>Ctrl+Z</b> ile geri alınır. Devam edilsin mi?'
    );
    if (!ok) return;
  }
  voiceEmbedRunning = true;
  const progressEl = document.getElementById(`ve-progress-${m.id}`);
  const setProgress = (t) => {
    if (progressEl) progressEl.textContent = t;
  };
  try {
    if (!speakerEmbedder) {
      setProgress('Model indiriliyor…');
      await loadSpeakerEmbedder((p) => {
        if (p && p.status === 'progress' && p.total) {
          setProgress(`Model indiriliyor… %${Math.round((p.loaded / p.total) * 100)}`);
        }
      });
    }
    setProgress('Ses çözümleniyor…');
    const res = await embedSegmentIndexes(m, targets, {
      onProgress: (n) => setProgress(`Ölçülüyor… ${n} bölüm`)
    });
    if (res.error === 'noaudio') {
      showToast('Ses dosyası bulunamadı.');
      return;
    }
    if (res.error === 'decode') {
      showToast('Ses çözümlenemedi.');
      return;
    }
    if (!res.points || !res.points.length) {
      showToast(`Ön-atama için yeterli uzunlukta bölüm yok (en az ${VOICE_EMBED_MIN_SEC} sn).`);
      return;
    }
    const plan = autoSpeakerPlan(res.points, { threshold: VOICE_EMBED_SAME, minSize: 1 });
    snapshotForUndo();
    ensureSpeakers(m);
    const usedNames = new Set((m.speakers || []).map((x) => x.name));
    let nextN = (m.speakers || []).length + 1;
    const nextName = () => {
      let n = nextN;
      while (usedNames.has(`Konuşmacı ${n}`)) n++;
      usedNames.add(`Konuşmacı ${n}`);
      nextN = n + 1;
      return `Konuşmacı ${n}`;
    };
    let assigned = 0;
    for (const g of plan) {
      const name = nextName();
      m.speakers.push({
        id: uid(),
        code: '',
        name,
        label: name,
        role: 'unspecified',
        gender: 'unspecified',
        ageRange: '',
        notes: '',
        pitch: null,
        pitchAt: null
      });
      for (const idx of g.indexes) {
        const sg = segs[idx];
        if (!sg) continue;
        setSegmentSpeakerByName(m, sg, name);
        sg.speakerAuto = true;
        assigned += 1;
      }
    }
    assignSpeakerCodes(m.speakers);
    m.speakerAutoAt = new Date().toISOString();
    logEvent(m, 'Konuşmacılar ön-atandı', `${plan.length} konuşmacı · ${assigned} bölüm (anonim benzerlik; kimlik değil)`);
    persist();
    const scroll = captureSegScroll(m);
    await renderAudioList();
    restoreSegScroll(m, scroll, activeSegIndex(m));
    renderSpeakersPanel(m);
    renderSpeakerSegmentTable(m);
    renderOverview();
    setProgress(`${plan.length} konuşmacı · ${assigned} bölüm ön-atandı`);
    showToast(
      `${plan.length} konuşmacı ön-atandı · ${assigned} bölüm. Dinleyip düzeltin; yanlışsa konuşmacıyı değiştirin veya yeni ekleyin (Ctrl+Z ile geri alınır).`
    );
  } catch (e) {
    showToast(`Ön-atama başarısız: ${e && e.message ? e.message : 'bilinmeyen hata'}`);
    if (progressEl) progressEl.textContent = 'Ön-atama başarısız.';
  } finally {
    voiceEmbedRunning = false;
  }
}

// BÖLÜM BAZINDA TAHMİN (v2.302): seçili bölümün konuşmacısını mevcut
// konuşmacı profilleriyle karşılaştırıp "≈ S2" ÖNERİSİ üretir. Atama YAPMAZ;
// uzman "Uygula" der. Kimlik tespiti değildir.
async function suggestSpeakerForSegment(m, idx) {
  if (!m) return;
  const segs = m.segments || [];
  const target = segs[idx];
  if (!target) return;
  ensureSpeakers(m);
  const speakers = (m.speakers || []).filter((sp) => sp && sp.name);
  if (!speakers.length) {
    showToast('Önce konuşmacı belirleyin (otomatik ön-atama veya elle), sonra tahmin yapılabilir.');
    return;
  }
  if (voiceEmbedRunning) {
    showToast('Konuşmacı ölçümü zaten sürüyor; bitmesini bekleyin.');
    return;
  }
  if (!speakerEmbedder) {
    const ok = await askConfirm(
      'Bu bölümün konuşmacısını tahmin et',
      `Konuşmacı doğrulama modeli (WavLM-SV, q8) yaklaşık <b>${esc(fmtBytes(VOICE_EMBED_BYTES))}</b> indirilir (bir kez). ` +
        'Bu bölüm, mevcut konuşmacıların ses örnekleriyle karşılaştırılır ve bir <b>öneri</b> (≈ S2) üretilir. ' +
        '<b>Kimlik tespiti değildir</b>; atama yapılmaz, "Uygula" derseniz uygulanır.'
    );
    if (!ok) return;
  }
  voiceEmbedRunning = true;
  try {
    if (!speakerEmbedder) {
      await loadSpeakerEmbedder();
    }
    const idxSet = new Set([idx]);
    const perSpk = [];
    for (const sp of speakers) {
      const ids = speakerSegments(m, sp)
        .map((s) => segs.indexOf(s))
        .filter((i) => i >= 0 && i !== idx)
        .slice(0, 3);
      for (const i of ids) idxSet.add(i);
      perSpk.push({ code: sp.code || sp.name, ids });
    }
    const res = await embedSegmentIndexes(m, [...idxSet], {});
    if (res.error === 'noaudio') {
      showToast('Ses dosyası bulunamadı.');
      return;
    }
    if (res.error === 'decode') {
      showToast('Ses çözümlenemedi.');
      return;
    }
    const byIndex = new Map((res.points || []).map((p) => [p.index, p.vec]));
    const targetVec = byIndex.get(idx);
    if (!targetVec) {
      showToast(`Bu bölüm tahmin için çok kısa (en az ${VOICE_EMBED_MIN_SEC} sn) veya ses yok.`);
      return;
    }
    const candidates = [];
    for (const g of perSpk) {
      const vecs = g.ids.map((i) => byIndex.get(i)).filter(Boolean);
      if (!vecs.length) continue;
      candidates.push({ code: g.code, vec: embeddingCentroid(vecs) });
    }
    if (!candidates.length) {
      showToast('Karşılaştırılacak konuşmacı örneği yok (her konuşmacıda en az bir uzun bölüm gerekir).');
      return;
    }
    const best = bestSpeakerMatch(targetVec, candidates);
    m.__spkSuggest = { idx, code: best.code, sim: best.sim, match: best.match, at: Date.now() };
    renderSegDetail(m);
    renderSpeakerSegmentTable(m);
    showToast(
      best.match === 'none'
        ? `Belirgin eşleşme yok (en yakın ≈ ${best.code || '—'} ${Number(best.sim).toFixed(2)}).`
        : `Öneri: ≈ ${best.code} · ${Number(best.sim).toFixed(2)}${best.match === 'uncertain' ? ' (belirsiz)' : ''}. Uygulamak için “Uygula”.`
    );
  } catch (e) {
    showToast(`Tahmin başarısız: ${e && e.message ? e.message : 'bilinmeyen hata'}`);
  } finally {
    voiceEmbedRunning = false;
  }
}

// Kayıttaki konuşmacılar için perde ölçümü. Her konuşmacının bölümlerinden
// birkaç örnek alınır, ortanca (medyan) perde hesaplanır. Ölçüm tek seferde
// yapılır ve kayda bağlı saklanır.
async function measureSpeakerPitch(m) {
  const c = currentCase();
  const blob = await getAudioBlob(c, m);
  if (!blob) {
    showToast('Ses dosyası bulunamadı.');
    return;
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  const ctx = new AC();
  let audio;
  try {
    audio = await ctx.decodeAudioData(await blob.arrayBuffer());
  } catch (e) {
    await ctx.close();
    showToast('Ses çözümlenemedi.');
    return;
  }
  const sr = audio.sampleRate;
  // TÜM kanallar (v2.92). Öncesinde yalnız kanal 0 okunuyordu; konuşma sağ
  // kanalda ise perde "ölçülemedi" çıkıyordu. Her bölüm için en yüksek
  // enerjili kanal seçilir.
  const chCount = audio.numberOfChannels;
  const channels = [];
  for (let ch = 0; ch < chCount; ch++) channels.push(audio.getChannelData(ch));
  ensureSpeakers(m);
  for (const sp of m.speakers) {
    const segs = speakerSegments(m, sp.name).slice(0, 12);
    const vals = [];
    for (const sg of segs) {
      const st = secondsFromTimecode(sg.start);
      const en = secondsFromTimecode(sg.end);
      // Süresi olmayan bölümde de ölçüm yapılabilir: başlangıçtan pencere alınır.
      const mid = en > st ? Math.floor(((st + en) / 2) * sr) : Math.floor(st * sr) + Math.floor(sr * 0.2);
      const a = Math.max(0, mid - Math.floor(sr * 0.2));
      const b = Math.min(channels[0].length, mid + Math.floor(sr * 0.2));
      // Bölüm aralığındaki en yüksek enerjili kanal (konuşma tek kanalda olabilir).
      const segChannels = channels.map((c) => c.subarray(a, b));
      const pick = pickActiveChannel(segChannels);
      const f = detectPitchHz(segChannels[pick.index], sr);
      if (f) {
        // Oktav belirsizliğini de ölç (v2.101): rapora tek bir kesin sayı
        // yazmadan önce "oktav yukarıda olabilir mi" bilinmeli.
        const amb = detectPitchAmbiguity(segChannels[pick.index], sr, f);
        vals.push({ hz: f, ambiguous: !!(amb && amb.ambiguous), octaveHz: (amb && amb.octaveHz) || null });
      }
    }
    if (vals.length) {
      // Medyan: perde tahminleri arasında en dayanıklı özet.
      vals.sort((a, b) => a.hz - b.hz);
      const med = vals[Math.floor(vals.length / 2)];
      sp.pitch = med.hz;
      sp.pitchSamples = vals.length;
      // Oktav belirsizse raporda tek sayı iddia edilmez (v2.101).
      const ambCount = vals.filter((v) => v.ambiguous).length;
      sp.pitchAmbiguous = ambCount > 0;
      sp.pitchOctaveHz = med.octaveHz;
      sp.pitchAt = new Date().toISOString();
    } else {
      sp.pitch = null;
      sp.pitchAmbiguous = false;
      sp.pitchOctaveHz = null;
      sp.pitchAt = new Date().toISOString();
    }
  }
  await ctx.close();
  logEvent(m, 'Konuşmacı perde ölçümü', `${m.speakers.length} konuşmacı için perde tahmini hesaplandı`);
  persist();
  refreshMeasurementPanel(m);
  renderSpeakersPanel(m); // Perde ölçümü tüm ses listesini yeniden çizmez; yalnızca konuşmacı paneli
  // güncellenir. Böylece sayfa yerinde kalır, kaydırma ve odak korunur.
  showToast('Konuşmacı perde ölçümü tamamlandı.');
}
// ---- Ölçüm durumu (v2.269) ----------------------------------------------
// TEK KAYNAK: hangi ölçüm yapıldı, ne zaman. Ekrandaki durum çipleri ve
// "Tüm ölçümleri yap" bu listeden beslenir; ölçüm fonksiyonları da aynı
// anahtarları yazar (levels.at, speaker.pitchAt, voiceCheck.at).
// Spektrogram bir ÖLÇÜM değil, İNCELEME BEYANIDIR (spectrogramReviewed):
// toplu ölçüme DAHİL EDİLMEZ, elle işaretlenir.
function measurementStatus(m) {
  const lv = m && m.levels;
  const speakers = (m && m.speakers) || [];
  const withPitch = speakers.filter((sp) => sp && sp.pitchAt);
  const vc = m && m.voiceCheck;
  return [
    {
      key: 'levels',
      label: 'Seviye ve kırpılma',
      done: !!(lv && lv.ok && lv.schema === LEVELS_SCHEMA),
      at: (lv && lv.at) || '',
      detail: '',
      manual: false
    },
    {
      key: 'pitch',
      label: 'Konuşmacı perdesi',
      done: withPitch.length > 0 && withPitch.length === speakers.length,
      at: withPitch.length ? withPitch.map((sp) => sp.pitchAt).sort().slice(-1)[0] : '',
      detail: speakers.length ? `${withPitch.length}/${speakers.length} konuşmacı` : 'konuşmacı yok',
      manual: false
    },
    {
      key: 'voice',
      label: 'Ses tutarlılığı',
      done: !!(vc && vc.ok),
      at: (vc && vc.at) || '',
      detail: vc && vc.ok ? `${(vc.outliers || []).length} şüpheli` : '',
      manual: false
    },
    {
      key: 'wer',
      label: 'WER (referans)',
      done: werStatus(m).ready,
      at: '',
      detail: werStatus(m).ready ? fmtWer(werStatus(m).result.ratio) : 'referans yok',
      manual: true // düğmeyle ölçülmez: referans varsa kendiliğinden hesaplanır
    },
    {
      key: 'spec',
      label: 'Spektrogram incelemesi',
      done: !!(m && m.spectrogramReviewed),
      at: (m && m.spectrogramReviewed && m.spectrogramReviewed.at) || '',
      detail: '',
      manual: true
    }
  ];
}
// Toplu ölçüm sırası. Spektrogram YOK (beyan); sessizlik bölüm bazındadır.
const MEASURE_ALL_STEPS = ['levels', 'pitch', 'voice'];
function measurementStatusText(item) {
  if (!item.done) return item.detail ? `yapılmadı · ${item.detail}` : 'yapılmadı';
  const t = item.at ? new Date(item.at) : null;
  const clock = t && !isNaN(t) ? t.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }) : '';
  return [clock, item.detail].filter(Boolean).join(' · ');
}
function measurementPanelHtml(m) {
  const items = measurementStatus(m);
  const chips = items
    .map(
      (it) =>
        `<span class="ms-chip ${it.done ? 'done' : 'todo'}${it.manual ? ' manual' : ''}" title="${esc(it.label)}: ${esc(measurementStatusText(it))}${it.manual ? ' — toplu ölçüme dâhil değildir' : ''}">${esc(it.label)}<span class="ms-state">${esc(measurementStatusText(it))}</span></span>`
    )
    .join('');
  return `<div class="pane-section measure-block"><div class="pane-title">Ölçümler<span class="info-i" tabindex="0" data-tip="Tepe/RMS, kırpılma, gürültü tabanı, konuşmacı perdesi ve ses tutarlılığı ses dosyasından hesaplanır. Ölçülmeyen değer rapora yazılmaz. Spektrogram incelemesi bir uzman beyanıdır; toplu ölçüme dâhil değildir.">i</span></div><div class="ms-chips">${chips}</div><div class="evidence-actions"><button class="mini-button primary" data-measure-all="${esc(m.id)}" title="Seviye/kırpılma + konuşmacı perdesi + ses tutarlılığını sırayla yeniden ölçer. Uzun kayıtta birkaç dakika sürebilir; ilerleme bildirilir.">Tüm ölçümleri yap</button><span class="ms-note">Sırayla: seviye → konuşmacı perdesi → ses tutarlılığı. Spektrogram incelemesi elle işaretlenir.</span></div></div>`;
}
function refreshMeasurementPanel(m) {
  const host = document.getElementById(`measure-panel-${m.id}`);
  if (!host) return;
  host.innerHTML = measurementPanelHtml(m);
}
// TOPLU ÖLÇÜM (v2.269): tek düğme, sıralı çalışır, her adımı bildirir.
// Aynı anda iki kez çalışmaz (çift decode yok). Hata olursa DURUR ve söyler.
let measureAllRunning = false;
async function measureAllFor(m) {
  if (measureAllRunning) {
    showToast('Ölçüm zaten sürüyor; bitmesini bekleyin.');
    return;
  }
  measureAllRunning = true;
  const steps = [
    ['levels', 'Seviye ve kırpılma', measureLevels],
    ['pitch', 'Konuşmacı perdesi', measureSpeakerPitch],
    ['voice', 'Ses tutarlılığı', measureSpeakerConsistency]
  ];
  let okCount = 0;
  try {
    for (let i = 0; i < steps.length; i++) {
      const [key, label, fn] = steps[i];
      if (key === 'voice' && !((m.segments || []).length)) {
        showToast(`${label}: bölüm yok, atlandı.`);
        continue;
      }
      if (key === 'pitch' && !((m.speakers || []).length)) {
        showToast(`${label}: konuşmacı yok, atlandı.`);
        continue;
      }
      showToast(`Ölçüm ${i + 1}/${steps.length}: ${label}…`);
      await fn(m);
      okCount++;
      refreshMeasurementPanel(m);
    }
  } catch (e) {
    showToast(`Ölçüm sırasında hata: ${e && e.message ? e.message : 'bilinmeyen'}`, true);
  } finally {
    measureAllRunning = false;
    refreshMeasurementPanel(m);
  }
  const st = measurementStatus(m);
  const todo = st.filter((x) => !x.manual && !x.done).map((x) => x.label);
  showToast(
    todo.length
      ? `Ölçüm tamamlandı (${okCount}/${steps.length}); eksik: ${todo.join(', ')}.`
      : `Ölçümler tamam: ${okCount}/${steps.length} adım çalıştı.`
  );
}
// Kaydın tamamı için seviye ölçümü: tepe/RMS, tepe kırpılma, gürültü tabanı ve
// sinyal/gürültü oranı. Sonuç kayda bağlanır ve rapora "Seviye ölçümü" satırı
// olarak yalnızca gerçekten ölçüldüyse yazılır.
async function measureLevels(m) {
  const c = currentCase();
  const blob = await getAudioBlob(c, m);
  if (!blob) {
    showToast('Ses dosyası bulunamadı.');
    return;
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  // Ölçüm, dosyanın kendi örnekleme hızında yapılır. Aksi hâlde tarayıcı
  // 48 kHz'e yeniden örnekler ve bant genişliği dosyanın gerçek üst sınırından
  // yüksek görünür; bu da rapora yanlış bir "geniş bant" izlenimi yazdırır.
  const nativeRate = Number(m.tech?.sampleRate) || 0;
  let ctx;
  try {
    ctx = nativeRate ? new AC({ sampleRate: nativeRate }) : new AC();
  } catch (e) {
    ctx = new AC();
  }
  let audio;
  try {
    audio = await ctx.decodeAudioData(await blob.arrayBuffer());
  } catch (e) {
    await ctx.close();
    showToast('Ses çözümlenemedi.');
    return;
  }
  // KANAL KANAL ölçüm (v2.91). Öncesinde tüm kanallar ortalamayla tek
  // "mono"ya indiriliyordu; ses yalnız bir kanalda ise tepe −6 dB düşük,
  // tek kanaldaki kırpılma tamamen görünmez oluyordu. Artık tepe ve kırpılma
  // en kötü kanaldan raporlanır; gürültü tabanı/SNR mono karışımdan.
  const chCount = audio.numberOfChannels;
  const channels = [];
  for (let ch = 0; ch < chCount; ch++) channels.push(audio.getChannelData(ch));
  const lv = analyzeChannelLevels(channels, audio.sampleRate);
  // Stereo ise kanal dengesi, faz ilişkisi ve DC kayması da ölçülür.
  const stereo = chCount === 2 ? analyzeStereo(audio.getChannelData(0), audio.getChannelData(1), audio.sampleRate) : null;
  // Etkin bant genişliği tüm spektrumun ölçüsüdür; mono karışım burada
  // doğrudur (bant sınırlaması kanallardan bağımsızdır).
  const lenAll = audio.length;
  const mono = new Float32Array(lenAll);
  for (let ch = 0; ch < chCount; ch++) {
    const d = audio.getChannelData(ch);
    for (let i = 0; i < lenAll; i++) mono[i] += d[i] / chCount;
  }
  const rolloff = spectralRolloff(mono, audio.sampleRate);
  await ctx.close();
  if (!lv.ok) {
    showToast('Ölçüm yapılamadı: kayıt boş görünüyor.');
    return;
  }
  m.levels = {
    ...lv,
    schema: LEVELS_SCHEMA,
    channels: chCount,
    analysisRate: audio.sampleRate,
    stereo: stereo && stereo.ok ? stereo : null,
    rolloff: rolloff || null,
    at: new Date().toISOString()
  };
  // Günlüğe hangi kanaldan ölçüldüğü de yazılır: sonradan denetlenebilir olsun.
  const chInfo = lv.channels > 1 ? ` · tepe kanal ${lv.peakChannel}` : '';
  const clipInfo = lv.clippedSamples > 0 ? ` (kanal ${lv.clipChannel})` : '';
  logEvent(m, 'Seviye ölçümü', `Tepe ${lv.peakDb.toFixed(1)} dBFS · RMS ${lv.rmsDb.toFixed(1)} dBFS · kırpılma %${(lv.clippedRatio * 100).toFixed(3)}${clipInfo}${chInfo}`);
  persist();
  refreshMeasurementPanel(m);
  renderAudioList();
  renderOverview();
  showToast('Seviye ölçümü tamamlandı.');
}
// Seçili bölümün sessizlik oranını ölçer. Ses dosyası çözülür, aralık RMS
// tabanlı analyzeSilence ile incelenir ve sonuç bölüme bağlanır. Ölçüm
// deterministiktir; uydurma bir "konuşma olasılığı" üretilmez.
async function measureSegmentSilence(m, index) {
  const s = (m.segments || [])[index];
  if (!s) return;
  const c = currentCase();
  const blob = await getAudioBlob(c, m);
  if (!blob) {
    showToast('Ses dosyası bulunamadı.');
    return;
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  const ctx = new AC();
  let audio;
  try {
    audio = await ctx.decodeAudioData(await blob.arrayBuffer());
  } catch (e) {
    await ctx.close();
    showToast('Ses çözümlenemedi.');
    return;
  }
  const sr = audio.sampleRate;
  // TÜM kanallar (v2.92). Öncesinde yalnız kanal 0 okunuyordu; konuşma sağ
  // kanalda ise bölüm "tamamen sessiz" sanılıyordu.
  const chCount = audio.numberOfChannels;
  const channels = [];
  for (let ch = 0; ch < chCount; ch++) channels.push(audio.getChannelData(ch));
  const st = secondsFromTimecode(s.start);
  const en = secondsFromTimecode(s.end);
  const stats = analyzeSilenceChannelAware(channels, sr, st, en);
  await ctx.close();
  if (!stats.ok) {
    showToast('Ölçüm için geçerli bir zaman aralığı gerekir.');
    return;
  }
  s.silence = { ...stats, schema: SILENCE_SCHEMA };
  // Hangi kanaldan ölçüldüğü günlüğe yazılır (v2.92): sonradan denetlenebilir.
  const chNote = stats.channels > 1 ? ` · kanal ${stats.channel}` : '';
  logEvent(m, 'Sessizlik ölçümü', `Bölüm ${index + 1}: %${Math.round(stats.ratio * 100)} sessiz (${stats.silentSec.toFixed(1)} sn)${chNote}`);
  persist();
  renderSegDetail(m);
  updateSegListItem(m, index);
  renderOverview();
  showToast(`Bölüm ${index + 1} sessizlik: %${Math.round(stats.ratio * 100)}`);
}
// Benzer perde aralığındaki konuşmacıları gruplama ÖNERİSİ. Kimlik tespiti
// değildir; yalnızca "bu etiketler benzer perdede, aynı kişi olabilir"
// ihtimalini uzmana hatırlatır. Uzman kararı esastır.
function suggestSpeakerMerges(m) {
  const sp = (m.speakers || []).filter((s) => s.pitch);
  const groups = [];
  for (const s of sp) {
    let placed = false;
    for (const g of groups) {
      const ref = g[0];
      if (Math.abs(s.pitch - ref.pitch) / ref.pitch < 0.12) {
        g.push(s);
        placed = true;
        break;
      }
    }
    if (!placed) groups.push([s]);
  }
  return groups.filter((g) => g.length > 1);
}

// Dosya geneli kişiler (K) — v2.293: Analiz sekmesinden Dosya bilgileri
// çekmecesine taşındı. Kayıt içi S1/S2 kodları ayrı kalır.
function casePersonsPanelHtml(c) {
  const persons = (c && c.speakers) || [];
  const linksOf = (pid) => {
    const out = [];
    for (const m of (c && c.materials) || [])
      for (const s of m.speakers || []) if (String(s.personId || '') === pid) out.push(`${m.name} (${s.code || s.name})`);
    return out;
  };
  const roleOpts = (r) =>
    SPEAKER_ROLE.map((x) => `<option value="${esc(x)}" ${normalizeSpeakerRole(r) === x ? 'selected' : ''}>${esc(SPEAKER_ROLE_LABEL[x] || x)}</option>`).join('');
  const genderOpts = (g) =>
    SPEAKER_GENDER.map((x) => `<option value="${esc(x)}" ${normalizeSpeakerGender(g) === x ? 'selected' : ''}>${esc(SPEAKER_GENDER_LABEL[x] || x)}</option>`).join('');
  const cards = persons
    .map((p) => {
      const links = linksOf(p.id);
      return `<div class="spk-card person-card" data-person-card="${esc(p.id)}">
      <div class="spk-card-head"><b>${esc(p.code || '')}${p.code ? ' · ' : ''}${esc(p.label || 'Etiketsiz')}</b><button class="mini-button danger" data-del-person="${esc(p.id)}" title="Kişi kaydını siler; bağlı konuşmacı etiketleri ve bölümler KORUNUR.">Sil</button></div>
      <div class="seg-row2"><div class="seg-field"><label>Kişi kodu</label><input data-person="${esc(p.id)}" data-person-key="code" value="${esc(p.code || '')}" placeholder="K1"></div><div class="seg-field"><label>Etiket</label><input data-person="${esc(p.id)}" data-person-key="label" value="${esc(p.label || '')}" placeholder="Örn. Kiracı"></div></div>
      <div class="seg-row2"><div class="seg-field"><label>Rol</label><select data-person="${esc(p.id)}" data-person-key="role">${roleOpts(p.role)}</select></div><div class="seg-field"><label>Cinsiyet</label><select data-person="${esc(p.id)}" data-person-key="gender">${genderOpts(p.gender)}</select></div></div>
      <div class="seg-row2"><div class="seg-field"><label>Yaş aralığı</label><input data-person="${esc(p.id)}" data-person-key="ageRange" value="${esc(p.ageRange || '')}" placeholder="30-40"></div><div class="seg-field"><label>Not</label><input data-person="${esc(p.id)}" data-person-key="notes" value="${esc(p.notes || '')}" placeholder="uzman gözlemi"></div></div>
      <small>${links.length} kayıt: ${esc(links.join(' · ') || 'henüz bağlı değil')} · <b>uzman eşleştirmesi</b></small></div>`;
    })
    .join('');
  return `<p class="drawer-note">Kişi kaydı yalnız eşleştirmedir; ses/metin silinmez. Konuşmacıları bağlamak için kayıt kartındaki <b>Aynı kişi</b> alanını kullanın.</p>${cards || '<div class="seg-empty-note">Henüz dosya geneli kişi yok.</div>'}<div class="evidence-actions"><button class="mini-button" data-add-case-person="1">＋ Kişi ekle</button></div>`;
}
function renderCasePersons() {
  const host = $('#casePersonsPanel');
  if (host) host.innerHTML = casePersonsPanelHtml(currentCase());
}
function updateCasePerson(id, key, value) {
  const c = currentCase();
  const p = ((c && c.speakers) || []).find((x) => x.id === id);
  if (!p) return;
  if (key === 'role') p.role = normalizeSpeakerRole(value);
  else if (key === 'gender') p.gender = normalizeSpeakerGender(value);
  else p[key] = String(value || '');
  persist();
}
function addCasePerson() {
  const c = currentCase();
  if (!c) return;
  c.speakers = c.speakers || [];
  const p = emptyCaseSpeaker({ label: 'Yeni kişi' });
  c.speakers.push(p);
  assignCaseSpeakerCodes(c.speakers);
  persist();
  renderCasePersons();
  showToast(`${p.code} · ${p.label} oluşturuldu. Konuşmacıları kayıt kartındaki “Aynı kişi” alanından bağlayın.`);
}
async function deleteCasePerson(pid) {
  const c = currentCase();
  const p = ((c && c.speakers) || []).find((x) => x.id === pid);
  if (!p) return;
  const links = [];
  for (const m of c.materials || [])
    for (const s of m.speakers || []) if (String(s.personId || '') === pid) links.push(s);
  const ok = await askConfirm(
    'Dosya geneli kişiyi sil',
    `${p.code ? p.code + ' · ' : ''}${p.label || 'Etiketsiz'} kişi kaydı silinecek. ` +
      (links.length ? `Bağlı ${links.length} konuşmacı ve bölümler KORUNUR; yalnız eşleştirme kaldırılır.` : 'Bağlı konuşmacı yok.') +
      ' Ses ve metin SİLİNMEZ.'
  );
  if (!ok) return;
  for (const s of links) s.personId = '';
  c.speakers = (c.speakers || []).filter((x) => x.id !== pid);
  persist();
  renderCasePersons();
  renderAudioList();
  showToast('Kişi kaydı silindi; ses/metin korundu.');
}

// Konuşmacı paneli: her konuşmacı için standart kod, etiket, rol, cinsiyet,
// yaş aralığı, not ve ölçülen perde. Bu bilgiler rapora "Konuşmacılar" tablosu
// olarak akar.
// KURAL (v2.79): seçeneklerin `value` değeri ASCII KOD'dur, görünen metin
// Türkçe ETİKETTİR. v2.78 ve öncesinde value'ya etiket yazılıyordu; şema kodu
// beklediği için kaydedilen rol/cinsiyet yeniden yüklemede 'unspecified'a
// düşüyordu (sessiz veri kaybı).
// Konuşmacı yöntem notu (v2.303): otomatik ön-atama kullanıldıysa ve kullanıcı
// raporda açtıysa döner; aksi hâlde '' (rapora satır YAZILMAZ).
function anyMaterialAutoUsed(c) {
  return ((c && c.materials) || []).some((m) => m && m.speakerAutoAt);
}
function speakerMethodNoteText(c) {
  return c && c.report && c.report.speakerMethod && anyMaterialAutoUsed(c) ? REPORT_TEXT.speakerMethodNote : '';
}
// BÖLÜM ↔ KONUŞMACI TABLOSU (v2.305). Konuşmacılar sekmesinde her bölümün
// konuşmacısını tek listede gösterir; atama buradan yapılır (Deşifre'ye gitmeden
// hızlı gözden geçir/düzelt). Kimlik değil; yalnız atama kolaylığı.
function renderSpeakerSegmentTable(m) {
  if (!m) return;
  const host = document.getElementById(`spk-seg-table-${m.id}`);
  if (!host) return;
  const note = document.getElementById(`spk-seg-note-${m.id}`);
  const segs = m.segments || [];
  if (!segs.length) {
    host.innerHTML = '<div class="seg-empty-note">Henüz bölüm yok. Önce Deşifre sekmesinde çözümleyin.</div>';
    if (note) note.textContent = '';
    return;
  }
  const filter = m.__spkSegFilter || 'all';
  const rows = [];
  let total = 0;
  let shown = 0;
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    const has = !!(s.speakerId || String(s.speaker || '').trim());
    if (filter === 'empty' && has) continue;
    if (filter === 'auto' && !s.speakerAuto) continue;
    total += 1;
    if (shown >= 400) continue;
    shown += 1;
    const sug = m.__spkSuggest && m.__spkSuggest.idx === i ? m.__spkSuggest : null;
    const sugCell = sug
      ? `<span class="sd-suggest${sug.match === 'uncertain' ? ' is-uncertain' : ''}" title="Ses benzerliği önerisi; kimlik değil.">≈ ${esc(sug.code || '—')} · ${Number(sug.sim || 0).toFixed(2)} <button type="button" class="mini-button" data-apply-suggest="${i}">Uygula</button></span>`
      : '';
    const badge = s.speakerAuto
      ? '<span class="sst-auto" title="Otomatik ön-atama (anonim ses benzerliği); dinleyip kontrol edin.">≈</span>'
      : '';
    rows.push(
      `<tr data-spk-seg-row="${i}"><td class="sst-time">${esc(s.start || '')}</td>` +
        `<td class="sst-text" title="${esc(s.text || '')}">${esc(clipText(s.text || '', 60) || '—')}</td>` +
        `<td class="sst-spk"><select data-seg="${i}" data-key="speaker" aria-label="Konuşmacı">${spkSelectOptions(m, s.speaker)}</select></td>` +
        `<td class="sst-badge">${badge}${sugCell}</td></tr>`
    );
  }
  if (!rows.length) {
    host.innerHTML = '<div class="seg-empty-note">Bu filtreye uyan bölüm yok.</div>';
    if (note) note.textContent = '';
    return;
  }
  host.innerHTML = `<table class="spk-seg-table"><thead><tr><th>ZAMAN</th><th>METİN</th><th>KONUŞMACI</th><th></th></tr></thead><tbody>${rows.join('')}</tbody></table>`;
  if (note) note.textContent = total > shown ? `${shown}/${total} bölüm gösteriliyor` : `${total} bölüm`;
}

function speakersPanelHtml(m) {
  const c = currentCase();
  const sp = m.speakers || [];
  const casePersons = (c && c.speakers) || [];
  const roleOptions = (role) =>
    SPEAKER_ROLE.map(
      (code) =>
        `<option value="${esc(code)}" ${normalizeSpeakerRole(role) === code ? 'selected' : ''}>${esc(SPEAKER_ROLE_LABEL[code] || code)}</option>`
    ).join('');
  const genderOptions = (gender) =>
    SPEAKER_GENDER.map(
      (code) =>
        `<option value="${esc(code)}" ${normalizeSpeakerGender(gender) === code ? 'selected' : ''}>${esc(SPEAKER_GENDER_LABEL[code] || code)}</option>`
    ).join('');
  const linkedSpeakers = (pid) => {
    const out = [];
    for (const mm of (c && c.materials) || []) {
      for (const s of mm.speakers || []) if (String(s.personId || '') === pid) out.push({ m: mm, sp: s });
    }
    return out;
  };
  const personName = (p) => `${p.code || ''}${p.code ? ' · ' : ''}${p.label || 'Etiketsiz'}`;
  const personOptions = (s) => {
    const cur = String(s.personId || '');
    const opts = ['<option value="">— Bağlı değil (yalnız bu kayıt) —</option>'];
    for (const p of casePersons) {
      const n = linkedSpeakers(p.id).length;
      opts.push(
        `<option value="${esc(p.id)}" ${cur === p.id ? 'selected' : ''}>${esc(personName(p))} (${n} kayıt)</option>`
      );
    }
    if (cur && !casePersons.some((p) => p.id === cur)) {
      opts.push(`<option value="${esc(cur)}" selected>Bağlı kişi bulunamadı (kayıt eksik)</option>`);
    }
    opts.push('<option value="__new__">＋ Yeni kişi (bu konuşmacıdan)</option>');
    return opts.join('');
  };

  const personCards = casePersons
    .map((p) => {
      const links = linkedSpeakers(p.id);
      const linkText = links.length
        ? links.map((x) => `${x.m.name} (${x.sp.code || x.sp.name})`).join(' · ')
        : 'henüz bağlı değil';
      return `<div class="spk-card person-card" data-person-card="${esc(p.id)}">
      <div class="spk-card-head"><b>${esc(personName(p))}</b><button class="mini-button danger" data-del-person="${esc(p.id)}" title="Bu dosya geneli kişiyi siler; ona bağlı konuşmacı etiketleri ve bölümler KORUNUR, yalnız eşleştirme kaldırılır.">Sil</button></div>
      <div class="seg-row2">
        <div class="seg-field"><label>Kişi kodu</label><input data-person="${esc(p.id)}" data-person-key="code" value="${esc(p.code || '')}" placeholder="K1" title="Dosya geneli kişi kodu; kayıt içi S1/S2'den ayrıdır."></div>
        <div class="seg-field"><label>Etiket</label><input data-person="${esc(p.id)}" data-person-key="label" value="${esc(p.label || '')}" placeholder="Örn. Kiracı"></div>
      </div>
      <div class="seg-row2">
        <div class="seg-field"><label>Rol</label><select data-person="${esc(p.id)}" data-person-key="role">${roleOptions(p.role)}</select></div>
        <div class="seg-field"><label>Cinsiyet (uzman beyanı)</label><select data-person="${esc(p.id)}" data-person-key="gender">${genderOptions(p.gender)}</select></div>
      </div>
      <div class="seg-row2">
        <div class="seg-field"><label>Yaş aralığı</label><input data-person="${esc(p.id)}" data-person-key="ageRange" value="${esc(p.ageRange || '')}" placeholder="Örn. 30-40"></div>
        <div class="seg-field"><label>Not / gözlem</label><input data-person="${esc(p.id)}" data-person-key="notes" value="${esc(p.notes || '')}" placeholder="Örn. aksanlı, kısık ses"></div>
      </div>
      <small>${links.length} kayıt: ${esc(linkText)} · <b>uzman eşleştirmesi</b></small>
    </div>`;
    })
    .join('');
  const codeNote = `<p class="spk-code-note"><b>S1, S2…</b> yalnız <b>BU kayıt</b> içinde geçerlidir; her kayıtta S1'den başlar. Aynı kişi birden çok kayıtta konuşuyorsa <b>K</b> koduyla (dosyalar arası kişi) bağlayın.</p>`;
  const personBlock = `<div class="person-panel">
    <div class="pane-title">Dosyalar arası kişiler (K)<span class="info-i" tabindex="0" data-tip="Aynı kişi birden çok kayıtta görünüyorsa burada TEK kayıt olarak tutulur. Eşleştirme uzman kanaatidir; uygulama kimlik tespiti yapmaz. Kayıt içi S1/S2 kodları ayrı kalır.">i</span></div>
    <p class="spk-person-note">Aynı kişi birden çok kayıtta görünüyorsa aşağıdaki kişiye bağlayın. Bu bir <b>uzman eşleştirmesidir</b>; otomatik kimlik tespiti değildir.</p>
    ${personCards || '<div class="seg-empty-note">Henüz dosya geneli kişi yok. Bir konuşmacıyı “＋ Yeni kişi” ile bağlayın.</div>'}
    <button class="mini-button" data-add-person="${esc(m.id)}" title="Boş bir dosya geneli kişi oluştur; sonra konuşmacıları bağlayın.">＋ Kişi ekle</button>
  </div>`;

  if (!sp.length)
    // Konuşmacı YOKKEN de gömme paneli görünür: ölçüm, atanmamış bölümler için
    // "hangi konuşmacıya benziyor" önerisi üretir (v2.280). Panel gizlenirse
    // öneriden hiç haberdar olunmaz.
    return `${voiceEmbedPanelHtml(m)}<div class="seg-empty-note">Konuşmacı etiketi girilmedi. Bölümlerde konuşmacı adı girdiğinizde burada listelenir.</div>`;
  const merges = suggestSpeakerMerges(m);
  const mergeNote = merges.length
    ? `<div class="halluc-note" style="background:#eef4fb;border-color:#d6e4f2;color:#2f6f95">Öneri (kimlik tespiti değildir): benzer perdede görünen etiketler — ${merges.map((g) => g.map((s) => esc(s.name)).join(' ≈ ')).join(' · ')}. Aynı kişi olup olmadığına uzman karar verir.</div>`
    : '';
  // v2.262 — kod çakışması: aynı kod iki kişide. Rapor iki kez "S1" yazar;
  // sessizce düzeltilmez, kullanıcı tek tıkla düzeltir (onay + geri alma).
  const codeConf = speakerCodeIssues(currentCase()).filter((i) => i.materialId === m.id);
  const codeBar = codeConf.length
    ? `<div class="warn-box spk-code-warn"><b>Kod çakışması:</b> ${codeConf
        .map((i) => `${esc(i.code)} → ${esc(i.names.join(', '))}`)
        .join(' · ')}. Rapor iki kez aynı kodu yazar; hangi bölümün kime ait olduğu okunamaz.<br><button class="mini-button" data-fix-spk-codes="${esc(m.id)}" title="Çakışan kodları sıradaki boş koda taşır. İlk konuşmacının kodu korunur; işlem geri alınabilir ve günlüğe yazılır.">Çakışan kodları düzelt (${codeConf.reduce((n, i) => n + i.speakerIds.length - 1, 0)})</button></div>`
    : '';
  // v2.265 — SES TUTARLILIĞI özeti: yalnız ölçüm yapıldıysa görünür.
  const vc = m.voiceCheck && m.voiceCheck.ok ? m.voiceCheck : null;
  const codeOf = (id) => {
    const rec = (m.speakers || []).find((x) => x.id === id);
    return rec ? rec.code || rec.name || '' : '';
  };
  const voiceBlock = vc
    ? `<div class="voice-check">
      <div class="vc-head"><b>Ses tutarlılığı</b><small>${vc.points.length} bölüm ölçüldü · ${vc.outliers.length} şüpheli · ${vc.changes.length} değişim şüphesi</small></div>
      <p class="spk-person-note">İşaretler yalnız <b>perde (f0)</b> ölçümüne dayanır; <b>kimlik tespiti değildir</b> ve hiçbir atama otomatik değiştirilmedi.</p>
      ${vc.outliers
        .slice(0, 20)
        .map(
          (o) =>
            `<div class="vc-row"><span class="vc-idx">Bölüm ${o.index + 1}</span><span class="vc-txt">${Math.round(o.hz)} Hz · atandığı profili ${Math.round(
              o.expectedHz
            )} Hz${o.nearestSpeakerId ? ` · en yakın: ${esc(codeOf(o.nearestSpeakerId))}` : ''}</span><button class="mini-button" data-voice-goto="${o.index}" title="Bu bölüme git">Git</button></div>`
        )
        .join('')}
      ${vc.changes
        .slice(0, 10)
        .map(
          (ch) =>
            `<div class="vc-row"><span class="vc-idx">Bölüm ${ch.index + 1}</span><span class="vc-txt">önceki ${Math.round(
              ch.prevHz
            )} Hz → ${Math.round(ch.hz)} Hz · konuşmacı değişmiş olabilir</span><button class="mini-button" data-voice-goto="${ch.prevIndex}" title="Bu bölüme git">Git</button></div>`
        )
        .join('')}
      ${vc.outliers.length > 20 ? `<div class="vc-row"><span class="vc-txt">… ${vc.outliers.length - 20} şüpheli daha (filtre: listede ⚠ ses)</span></div>` : ''}
    </div>`
    : '';
  const unused = unusedSpeakers(m);
  const cleanBar = unused.length
    ? `<div class="spk-toolbar"><span>${unused.length} konuşmacı hiçbir bölüme atanmamış; raporda görünmez.</span><button class="mini-button" data-clean-spk="${esc(m.id)}" title="Hiçbir bölüme atanmamış konuşmacıları listeden kaldır. Ses ve metinler silinmez.">Kullanılmayanları temizle (${unused.length})</button></div>`
    : '';
  const rows = sp
    .map((s) => {
      const segs = speakerSegments(m, s);
      const linkedPerson = casePersons.find((p) => p.id === String(s.personId || ''));
      const linkedNote = s.personId
        ? linkedPerson
          ? `Bağlı: ${personName(linkedPerson)}`
          : 'Bağlı kişi bulunamadı (kayıt eksik)'
        : '';
      const stat = speakerStats(m, s);
      // v2.264 — DOĞRULANDI KİLİDİ: künye doğrulanınca alanlar ve silme kilitlenir.
      const ver = isSpeakerVerified(s);
      const dis = ver ? ' disabled' : '';
      const verifyLabel = ver
        ? `✓ ${esc(REPORT_TEXT.speakerVerifiedSuffix)}${s.verifiedBy ? ` · ${esc(s.verifiedBy)}` : ''}`
        : 'Doğrulandı (kilitle)';
      const delTitle = ver
        ? 'Kilitli: silmek için önce doğrulama işaretini kaldırın.'
        : "Bu konuşmacıyı listeden ve rapor tablosundan kaldır. Ona atanmış bölümler 'Konuşmacı seçilmedi' olur; ses ve metin silinmez.";
      return `<div class="spk-card${ver ? ' is-verified' : ''}" data-spk-card="${esc(s.id)}">
      <div class="spk-card-head"><b>${esc(s.code || '')}${s.code ? ' · ' : ''}${esc(s.name)}</b><label class="spk-verify" title="Bu kişinin etiketi/rolü doğruysa işaretleyin: kart kilitlenir ve raporda 'doğrulandı' notu çıkar. Bu bir BÖLÜM ONAYI değildir. Kilidi açmak için işareti kaldırın."><input type="checkbox" data-spk-verify="${esc(s.id)}"${ver ? ' checked' : ''}> ${verifyLabel}</label><button class="mini-button danger" data-del-spk="${esc(m.id)}|${esc(s.id)}"${dis} title="${esc(delTitle)}">Sil</button></div>
      <div class="seg-row2">
        <div class="seg-field"><label>Kayıt içi kod (S)</label><span class="spk-code" title="Kod KİMLİKTİR: bölümler ve rapor bu kodla okunur; bu yüzden değiştirilemez. Görünen adı (etiket) aşağıdan değiştirebilirsiniz.">${esc(s.code || '—')}</span></div>
        <div class="seg-field"><label>Konuşmacı etiketi</label><input data-spk="${esc(s.id)}" data-spk-key="name" value="${esc(s.name)}" placeholder="Örn. Kiracı, Ev sahibi"${dis}></div>
      </div>
      <div class="seg-row2">
        <div class="seg-field"><label>Rol</label><select data-spk="${esc(s.id)}" data-spk-key="role"${dis}>${roleOptions(s.role)}</select></div>
        <div class="seg-field"><label>Cinsiyet (uzman beyanı)</label><select data-spk="${esc(s.id)}" data-spk-key="gender"${dis}>${genderOptions(s.gender)}</select></div>
      </div>
      <div class="seg-row2">
        <div class="seg-field"><label>Yaş aralığı</label><input data-spk="${esc(s.id)}" data-spk-key="ageRange" value="${esc(s.ageRange || '')}" placeholder="Örn. 30-40"${dis}></div>
        <div class="seg-field"><label>Not / gözlem</label><input data-spk="${esc(s.id)}" data-spk-key="notes" value="${esc(s.notes || '')}" placeholder="Örn. aksanlı, kısık ses"${dis}></div>
      </div>
      <div class="seg-row2">
        <div class="seg-field"><label>Dosyalar arası kişi (K)</label><select data-spk="${esc(s.id)}" data-spk-key="personId" title="Bu konuşmacıyı dosya geneli bir kişiye bağlar. Eşleştirme uzman kanaatidir; otomatik kimlik tespiti değildir."${dis}>${personOptions(s)}</select></div>
        ${linkedNote ? `<div class="seg-field"><label>Bağlantı</label><small>${esc(linkedNote)}</small></div>` : ''}
      </div>
      <div class="spk-actions">${
        segs.length
          ? `<button class="mini-button" data-sample-spk="${esc(m.id)}|${esc(s.id)}" title="Bu konuşmacının ilk bölümünden en çok 3 saniye dinle (kimliği kulağınızla eşleştirin).">▶ Örnek dinle</button>` +
            `<button class="mini-button" data-listen-spk="${esc(m.id)}|${esc(s.id)}" title="Bu konuşmacının TÜM bölümlerini sırayla dinle. Elle bir bölüm çalarsanız veya durdurursanız kuyruk iptal olur.">▶ Tüm bölümleri dinle</button>`
          : ''
      }</div>
      <small>${segs.length ? `${segs.length} bölüm · ${fmtShort(stat.totalSec)} · ${stat.first}–${stat.last}` : '<b class="spk-unused">hiçbir bölüme atanmamış — raporda görünmez</b>'} · ${s.pitch ? `ölçülen perde ≈ <b>${fmtHz(s.pitch)}</b> — ${esc(pitchHint(s.pitch))}${s.pitchSamples ? ` (${s.pitchSamples} örnek)` : ''}` : s.pitchAt ? 'perde ölçülemedi (ölçüm yapıldı)' : 'perde ölçülmedi'}</small>
    </div>`;
    })
    .join('');
  const embedBlock = voiceEmbedPanelHtml(m);
  return `${codeNote}${voiceBlock}${embedBlock}${codeBar}${cleanBar}${mergeNote}<div class="spk-list">${rows}</div>`;
}
// v2.279 — Gömme ölçümü paneli (Konuşmacılar bölümünde).
// v2.292 — benzer grup ataması: ONAY + snapshot + günlük; otomatik değil.
async function assignEmbeddingCluster(m, key) {
  const cl = ((m.voiceEmbed && m.voiceEmbed.clusters) || []).find((x) => x.key === key);
  if (!cl) return;
  const sel = document.querySelector(`[data-voice-cluster-target="${CSS.escape(m.id)}"]`);
  const sp = (m.speakers || []).find((s) => s.id === (sel && sel.value));
  if (!sp) {
    showToast('Önce hedef konuşmacı seçin (konuşmacı etiketi girilmiş olmalı).');
    return;
  }
  const ok = await askConfirm(
    'Grubu ata',
    `Grup ${key} (${cl.count} bölüm) “${sp.code ? sp.code + ' · ' : ''}${sp.name}” konuşmacısına atanacak. ` +
      'Onay ister; Ctrl+Z ile geri alınır. Ses/deşifre kanıtı DEĞİŞMEZ.'
  );
  if (!ok) return;
  snapshotForUndo('Grup ata');
  let n = 0;
  for (const idx of cl.indexes) {
    const sg = (m.segments || [])[idx];
    if (!sg) continue;
    setSegmentSpeakerByName(m, sg, sp.name);
    n += 1;
  }
  logEvent(m, 'speaker-cluster-assign', `Grup ${key} → ${sp.code ? sp.code + ' ' : ''}${sp.name} (${n} bölüm)`);
  const remaining = ((m.voiceEmbed && m.voiceEmbed.clusters) || [])
    .map((c) => ({ ...c, indexes: c.indexes.filter((i) => !cl.indexes.includes(i)) }))
    .filter((c) => c.indexes.length >= 2)
    .map((c, i) => ({
      ...c,
      key: String.fromCharCode(65 + i),
      count: c.indexes.length,
      first: c.indexes[0],
      last: c.indexes[c.indexes.length - 1]
    }));
  m.voiceEmbed.clusters = remaining;
  persist();
  await renderAudioList();
  refreshVoiceEmbedPanel(m);
  showToast(`Grup ${key} atandı: ${sp.code ? sp.code + ' · ' : ''}${sp.name} (${n} bölüm).`);
}

