const MERGE_CANDIDATE = { maxGapSec: 0.5, maxDurSec: 2, maxWords: 5, tol: 0.001 };
const SENTENCE_END_RE = /[.!?…]["'”’)\]]?$/;
const PLAYBACK_SPEEDS = [0.25, 0.5, 0.75, 1, 1.25, 1.5, 2];
