  const list = Array.isArray(segs) ? segs : [];
  const spans = [];
  let pos = 0;
  for (let i = 0; i < list.length; i++) {
    const w = list[i] && list[i].w;
    if (!w) {
      spans.push(null);
      continue;
    }
    let at = src.indexOf(w, pos);
    if (at < 0) at = src.indexOf(w);
    if (at < 0) {
      spans.push(null);
      continue;
    }
    spans.push([at, at + w.length]);
    pos = at + w.length;
  }
