  s6: 'Gerekçeli sonuç',
  s7: 'Ek listesi (başlıklar)',
  origin: 'Kayıt kökeni ve teslim zinciri',
  embedded: 'Gömülü metadata (beyan)',
  acquisition: 'Delil edinme ve doğrulama',
  speakers: 'Konuşmacılar',
  speakerDurations: 'Konuşmacı süreleri',
