$('#reportSections')?.addEventListener('click', (e) => {
  if (e.target.closest('[data-report-profile-save]')) {
    saveReportProfile();
    return;
  }
  if (e.target.closest('[data-report-profile-apply]')) {
    const s = document.querySelector('[data-report-profile-select]');
    if (s) applyReportProfile(s.value);
    return;
  }
  if (e.target.closest('[data-report-profile-del]')) {
    const s = document.querySelector('[data-report-profile-select]');
    if (s) deleteReportProfile(s.value);
    return;
  }
  if (e.target.closest('[data-report-block-add]')) {
    addReportBlock();
    return;
  }
  const place = e.target.closest('[data-report-place]');
  if (place) {
    toggleAnnexPlacement(place.dataset.reportPlace);
    return;
  }
  const bsave = e.target.closest('[data-report-block-save]');
  if (bsave) {
    saveReportBlockFromRow(bsave.dataset.reportBlockSave);
    return;
  }
  const bdel = e.target.closest('[data-report-block-del]');
  if (bdel) {
    removeReportBlock(bdel.dataset.reportBlockDel);
    return;
  }
  const tedit = e.target.closest('[data-report-title]');
  if (tedit) {
    const key = tedit.dataset.reportTitle;
    reportTitleEditKey = key;
    const c = currentCase();
    if (c) renderReportSections(c);
    requestAnimationFrame(() => {
      const inp = document.querySelector(`[data-report-title-input="${key}"]`);
      if (inp) {
        inp.focus();
        inp.select();
      }
    });
    return;
  }
  const tcancel = e.target.closest('[data-report-title-cancel]');
  if (tcancel) {
    const key = tcancel.dataset.reportTitleCancel;
    if (isFreeBlockKey(key)) cancelReportBlockEdit(key);
    else {
      reportTitleEditKey = null;
      const c = currentCase();
      if (c) renderReportSections(c);
    }
    return;
  }
  const mv = e.target.closest('[data-report-move]');
  if (mv) {
    moveReportSection(mv.dataset.reportMove, Number(mv.dataset.dir));
    return;
  }
  const amv = e.target.closest('[data-report-annex-move]');
  if (amv) {
    moveReportAnnex(amv.dataset.reportAnnexMove, Number(amv.dataset.dir));
    return;
  }
  if (e.target.closest('[data-report-annex-add]')) {
    addReportAnnex();
    return;
  }
  const adel = e.target.closest('[data-report-annex-del]');
  if (adel) {
    removeReportAnnex(adel.dataset.reportAnnexDel);
    return;
  }
  const b = e.target.closest('[data-report-sections-all]');
  if (!b) return;
  const c = currentCase();
  if (!c) return;
  c.report = c.report || {};
  c.report.sections =
    b.dataset.reportSectionsAll === 'on'
      ? emptyReportSections()
      : emptyReportSections(Object.fromEntries(REPORT_SECTION_DEFS.map((d) => [d.key, false])));
  persist();
  renderReport();
});
// Başlık düzenleme (v2.285): Enter uygular (change → kaydet), Esc vazgeçer.
$('#reportSections')?.addEventListener('keydown', (e) => {
  const inp = e.target.closest('[data-report-title-input]');
  const ta = e.target.closest('[data-report-block-text]');
  if (!inp && !ta) return;
  const key = inp ? inp.dataset.reportTitleInput : ta.dataset.reportBlockText;
  const free = isFreeBlockKey(key);
  if (e.key === 'Enter' && inp) {
    e.preventDefault();
    // Değer değişmemiş olsa da düzenlemeyi kapat (blur tek başına change
    // üretmez; kutu açık kalırdı). Serbest blokta metin de kaydedilir.
    if (free) saveReportBlockFromRow(key);
    else setReportSectionTitle(key, inp.value);
  } else if (e.key === 'Escape') {
    e.preventDefault();
    if (free) {
      cancelReportBlockEdit(key);
    } else {
      reportTitleEditKey = null;
      const c = currentCase();
      if (c) renderReportSections(c);
    }
  }
});
// Sürükle-bırak sıralama (v2.296). ↑↓ düğmeleri KORUNUR; sürükleme hızlandırıcıdır.
let rsecDrag = null;
$('#reportSections')?.addEventListener('dragstart', (e) => {
  const row = e.target.closest('[data-drag-kind][data-drag-key]');
  if (!row) return;
  rsecDrag = { kind: row.dataset.dragKind, key: row.dataset.dragKey };
  if (e.dataTransfer) {
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', rsecDrag.key);
  }
  row.classList.add('dragging');
});
$('#reportSections')?.addEventListener('dragover', (e) => {
  if (!rsecDrag) return;
  const row = e.target.closest('[data-drag-kind][data-drag-key]');
  if (!row || row.dataset.dragKind !== rsecDrag.kind || row.dataset.dragKey === rsecDrag.key) return;
  e.preventDefault();
  const r = row.getBoundingClientRect();
  const y = (e.clientY - r.top) / Math.max(1, r.height);
  const isAnnexTarget = row.dataset.dragKind === 'body' && row.dataset.dragKey === 'annex';
  const zone = rsecDrag.kind === 'annex' || isAnnexTarget ? (y < 0.5 ? 'before' : 'after') : y < 0.25 ? 'before' : y > 0.75 ? 'after' : 'under';
  row.dataset.dropZone = zone;
  document.querySelectorAll('#reportSections .drag-over, #reportSections .drop-before, #reportSections .drop-after, #reportSections .drop-under').forEach((x) => x.classList.remove('drag-over', 'drop-before', 'drop-after', 'drop-under'));
  row.classList.add('drag-over', `drop-${zone}`);
});
$('#reportSections')?.addEventListener('drop', (e) => {
  if (!rsecDrag) return;
  const row = e.target.closest('[data-drag-kind][data-drag-key]');
  if (!row || row.dataset.dragKind !== rsecDrag.kind) return;
  e.preventDefault();
  const src = rsecDrag;
  rsecDrag = null;
  document.querySelectorAll('#reportSections .dragging, #reportSections .drag-over, #reportSections .drop-before, #reportSections .drop-after, #reportSections .drop-under').forEach((x) => x.classList.remove('dragging', 'drag-over', 'drop-before', 'drop-after', 'drop-under'));
  if (row.dataset.dragKey === src.key) return;
  const zone = row.dataset.dropZone || (src.kind === 'annex' ? 'after' : 'under');
  let ok = true;
  if (src.kind === 'body') ok = moveSectionRelative(src.key, row.dataset.dragKey, zone);
  else moveReportAnnexTo(src.key, row.dataset.dragKey);
  if (ok) showToast(zone === 'under' ? 'Bölüm altına taşındı (Ctrl+Z ile geri alınır).' : 'Sıra değiştirildi (Ctrl+Z ile geri alınır).');
});
$('#reportSections')?.addEventListener('dragend', () => {
  rsecDrag = null;
  document.querySelectorAll('#reportSections .dragging, #reportSections .drag-over, #reportSections .drop-before, #reportSections .drop-after, #reportSections .drop-under').forEach((x) => x.classList.remove('dragging', 'drag-over', 'drop-before', 'drop-after', 'drop-under'));
});
// Ek düzenleyici (v2.227): yazarken model, çıkınca önizleme (odak korunur).
